38	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
39	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
40	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
41	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
42	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
